UPDATE articulos a SET contenido=(SELECT string_agg(coalesce(v.texto,substring(a.contenido from v.inicio for v.largo)),'' ORDER BY v.orden) FROM (VALUES (0, 1, 43, NULL::text),(1,0,0,E'<thead><tr><th scope="col">Condición de aceptación del sistema o componente mecánico</th><th scope="col">Cumple</th><th scope="col">No cumple</th><th scope="col">N/A*</th></tr></thead>'),(2, 44, 7, NULL::text),(3, 172, 64, NULL::text),(4,0,0,E'<td colspan="3">'),(5, 240, 589, NULL::text)) v(orden,inicio,largo,texto)) WHERE a.id='6fd497d0-9f5a-5b0e-bf13-bdc3e37b9948' AND md5(a.contenido)='febe606a8907367e999721b92c4159d9' RETURNING a.id,md5(a.contenido) hash;